export interface GenreRecord {
  id: string;
  name: string;
  blurb: string;
  count: number;
}

export interface BookCoverColors {
  /** Deep panel colour sampled from the artwork. */
  color: string;
  /** Light tint used for the author line. */
  accent: string;
}

/** Catalog metadata for a single book (generated by scripts/import-books.mjs). */
export interface BookRecord {
  id: string;
  title: string;
  subtitle?: string;
  author: string;
  authorId: string;
  authorSort: string;
  translator?: string;
  illustrator?: string;
  /** Year of first publication; negative numbers are BCE. */
  year: number;
  genres: string[];
  tagline: string;
  /** Sanitized HTML (<p>, <i>, <em> only). */
  description: string;
  subjects: string[];
  collections: string[];
  words: number;
  chapters: number;
  /** Flesch reading-ease score (higher = easier). */
  readingEase: number;
  language: string;
  cover: BookCoverColors;
  source: string;
}

export interface TocChapter {
  title: string;
  part?: string;
  words: number;
}

export interface BookToc {
  chapters: TocChapter[];
}

export type LengthBucket = 'short' | 'medium' | 'long';
export type EraBucket = 'ancient' | 'early-modern' | 'romantic' | 'victorian' | 'modern';
export type EaseBucket = 'easy' | 'moderate' | 'challenging';
